import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.DMvgf4hZ.js";const f=JSON.parse('{"title":"下载与安装","description":"","frontmatter":{},"headers":[],"relativePath":"guide/install.md","filePath":"guide/install.md","lastUpdated":1794752882000}'),l={name:"guide/install.md"};function n(s,e,d,i,p,c){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="下载与安装" tabindex="-1">下载与安装 <a class="header-anchor" href="#下载与安装" aria-label="Permalink to &quot;下载与安装&quot;">​</a></h1><h2 id="客户端安装" tabindex="-1">客户端安装 <a class="header-anchor" href="#客户端安装" aria-label="Permalink to &quot;客户端安装&quot;">​</a></h2><p>当前版本 <strong>2.0.11</strong>，由本仓库自行构建。下表链接直接指向发布文件，历史版本见 <a href="https://github.com/dolfly/toonflow/releases" target="_blank" rel="noreferrer">Releases</a>。</p><table tabindex="0"><thead><tr><th>操作系统</th><th>下载文件</th></tr></thead><tbody><tr><td>Windows x64</td><td><a href="https://github.com/dolfly/toonflow/releases/download/v2.0.11/toonflow-2.0.11-Setup.exe" target="_blank" rel="noreferrer">toonflow-2.0.11-Setup.exe</a></td></tr><tr><td>Windows ARM64</td><td><a href="https://github.com/dolfly/toonflow/releases/download/v2.0.11/toonflow-2.0.11-win-arm64-Setup.exe" target="_blank" rel="noreferrer">toonflow-2.0.11-win-arm64-Setup.exe</a></td></tr><tr><td>macOS Apple Silicon（ARM64，macOS 14 及以上）</td><td><a href="https://github.com/dolfly/toonflow/releases/download/v2.0.11/toonflow-2.0.11-macos-arm64.dmg" target="_blank" rel="noreferrer">toonflow-2.0.11-macos-arm64.dmg</a></td></tr><tr><td>macOS Intel（x64，macOS 14 及以上）</td><td><a href="https://github.com/dolfly/toonflow/releases/download/v2.0.11/toonflow-2.0.11-macos-x64.dmg" target="_blank" rel="noreferrer">toonflow-2.0.11-macos-x64.dmg</a></td></tr><tr><td>Linux x64（Debian / Ubuntu）</td><td><a href="https://github.com/dolfly/toonflow/releases/download/v2.0.11/toonflow-2.0.11-linux-x64.deb" target="_blank" rel="noreferrer">toonflow-2.0.11-linux-x64.deb</a></td></tr><tr><td>Linux ARM64（Debian / Ubuntu）</td><td><a href="https://github.com/dolfly/toonflow/releases/download/v2.0.11/toonflow-2.0.11-linux-arm64.deb" target="_blank" rel="noreferrer">toonflow-2.0.11-linux-arm64.deb</a></td></tr><tr><td>Android ARM64</td><td><a href="https://github.com/dolfly/toonflow/releases/download/v2.0.11/toonflow-2.0.11-android-arm64.apk" target="_blank" rel="noreferrer">toonflow-2.0.11-android-arm64.apk</a></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">签名与公证状态</p><p>本仓库没有配置代码签名证书，<strong>Windows 安装包未做数字签名，macOS 应用与 DMG 未使用 Developer ID 签名、未做 Apple 公证</strong>。macOS 首次打开若被 Gatekeeper 拦截，按下方“macOS 无法安装或打开时的处理方法”操作即可。</p><p>客户端增量更新通道也未启用（未配置更新托管上传密钥），请直接下载安装包覆盖安装。</p></div><p>Android 版仅支持 ARM64 设备，下载上表中的 <code>toonflow-2.0.11-android-arm64.apk</code> 安装。手机内置本地 Bun 后端，可独立运行；也可从首页「设备互联」扫码或手动连接已开启共享的电脑或远程后端（支持局域网与公网）。</p><p>Windows 安装器会自动检测并安装 WebView2；如果安装后打开闪退，请前往 <a href="https://developer.microsoft.com/microsoft-edge/webview2/" target="_blank" rel="noreferrer">WebView2 下载页面</a> 手动安装运行时。</p><p>Windows 的 Intel / AMD 电脑选择 <code>toonflow-2.0.11-Setup.exe</code>，ARM64 电脑选择 <code>toonflow-2.0.11-win-arm64-Setup.exe</code>。ARM64 需要 .NET Framework 4.8.1，较新的 Windows 11 已内置。</p><p>Linux 选择对应架构的 <code>toonflow-2.0.11-linux-x64.deb</code> 或 <code>toonflow-2.0.11-linux-arm64.deb</code>，在下载目录执行 <code>sudo apt install ./安装包文件名.deb</code>，安装后从应用菜单打开。安装需要联网；apt 会准备 FFmpeg、curl、unzip、CA 证书等依赖，安装脚本在解包应用前下载固定版本的 Bun 并校验大小与 SHA-256，配置阶段再安装运行时。下载或校验失败会在解包前中止安装。</p><p>macOS 两种架构均使用统一的 Electrobun SDK，最低支持 macOS 14。选择对应架构的 <code>toonflow-2.0.11-macos-arm64.dmg</code> 或 <code>toonflow-2.0.11-macos-x64.dmg</code>，打开后将 <code>toonflow.app</code> 拖入“应用程序”，再从“应用程序”打开 Toonflow。本仓库的构建未使用 Developer ID Application 签名，也未做 Apple 公证；需要签名版的用户可改用上游 <a href="https://github.com/HBAI-Ltd/Toonflow-app/releases" target="_blank" rel="noreferrer">HBAI-Ltd/Toonflow-app</a> 的正式版本。旧版 Intel Mac 客户端首次迁移时须下载完整 DMG 覆盖安装，不能通过旧版增量更新直接迁移；安装前退出应用并备份原数据目录。</p><h3 id="macos-无法安装或打开时的处理方法" tabindex="-1">macOS 无法安装或打开时的处理方法 <a class="header-anchor" href="#macos-无法安装或打开时的处理方法" aria-label="Permalink to &quot;macOS 无法安装或打开时的处理方法&quot;">​</a></h3><p><strong>1. 在“隐私与安全性”中允许 Toonflow</strong></p><p>如果提示“无法验证开发者”或“Apple 无法检查 App 是否包含恶意软件”，先尝试打开 Toonflow，再前往“系统设置 → 隐私与安全性”，找到 Toonflow 被阻止的提示，点击“仍要打开”，并按提示确认。详见 <a href="https://support.apple.com/zh-cn/102445" target="_blank" rel="noreferrer">Apple 官方说明</a>。</p><p><strong>2. 仍因系统隔离限制无法打开时，再尝试移除隔离属性</strong></p><p>确认应用来自官方发布页，并已放入“应用程序”后，在终端执行以下命令，再重新打开。应用名称或安装位置不同时，请调整路径。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.apple.quarantine</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/toonflow.app</span></span></code></pre></div><p><strong>3. 最后手段：临时允许任何来源的 App</strong></p><p>前两种方法均无效且确认应用来源可信时，可尝试在终端执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --master-disable</span></span></code></pre></div><p>随后打开“系统设置 → 隐私与安全性”，在“安全性”中的“允许从以下位置下载的 App”选择“任何来源”（如果系统提供该选项），并按提示确认。不同 macOS 版本的选项与命令支持可能不同。</p><div class="warning custom-block"><p class="custom-block-title">安全提示</p><p>此操作会放宽所有 App 的安全限制。完成后建议将允许来源恢复为“App Store 和被认可的开发者”。</p></div><h2 id="安装完成后" tabindex="-1">安装完成后 <a class="header-anchor" href="#安装完成后" aria-label="Permalink to &quot;安装完成后&quot;">​</a></h2><p>装好客户端即可继续<a href="./#配置模型">配置模型</a>，然后开始建项目。想用 Docker 或服务器方式运行 Web 与 Server，见<a href="/toonflow/deploy/">服务端部署</a>。</p>',23)])])}const m=o(l,[["render",n]]);export{f as __pageData,m as default};
